import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-08","description":"2026-09-08 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-08","description":"2026-09-08 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-08.md","filePath":"zh/runtime/daily-intelligence/2026-09-08.md","lastUpdated":1788922207000}'),n={name:"zh/runtime/daily-intelligence/2026-09-08.md"};function i(s,e,p,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="agent-核心研究与竞品动态-·-2026-09-08" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-08 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-08" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-08&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 仅收录达到 meaningful new developments 阈值的公开技术与产品变化。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>本日最重要的信号集中在三条线上：<strong>赵岳主动纠正 GRADE 的结构性结论；Paperclip 把共享数字员工的真人来源身份做成运行时合同；Codex 则把 Human Verification 推进到 Secure Enclave 与生物识别签名。</strong></p><h2 id="_1-yue-zhao-赵岳-grade-修复依赖图构造缺陷-并主动撤回一项核心结构性结论" tabindex="-1">1. Yue Zhao（赵岳）/ GRADE：修复依赖图构造缺陷，并主动撤回一项核心结构性结论 <a class="header-anchor" href="#_1-yue-zhao-赵岳-grade-修复依赖图构造缺陷-并主动撤回一项核心结构性结论" aria-label="Permalink to &quot;1. Yue Zhao（赵岳）/ GRADE：修复依赖图构造缺陷，并主动撤回一项核心结构性结论&quot;">​</a></h2><p><strong>状态：MERGED / RESEARCH CLAIM CORRECTED</strong></p><p>赵岳本人提交了 GRADE 修正：<a href="https://github.com/yzhao062/grade/commit/a9a87a13866e6410f83664bf8a59642fb36aac8e" target="_blank" rel="noreferrer">commit a9a87a1</a>。核心问题是一个名为 <code>last_on_id</code> 的映射实际通过 <code>setdefault</code> 保存 identifier 的<strong>第一个 producer</strong>，而下游逻辑却假设取得的是最近 producer。修正后，大量依赖边和 dependency span 发生变化；此前另一处 hash-order 缺陷也被一并纠正，修复后 transfer / within-corpus cells 在多组 <code>PYTHONHASHSEED</code> 下保持一致。</p><p>更重要的是，赵岳明确撤回“dependency layer 比 run size 更能预测失败”的原表述：旧基准只是线性 size baseline，不能排除依赖特征仅编码了 run size 的非线性函数。新的 nonlinear size baseline 与 null/chain controls 表明，原 structural superiority claim 不再成立；Execution-layer 的 fault localization 结论不受该修正影响。</p><p><strong>为什么重要：</strong> Graph feature 看起来更复杂，不等于它提供了独立信息。研究结论必须用足够强的 null / nonlinear baseline 做对照。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 未来若 EVAL 要证明 dependency graph、audit graph、recovery graph 的独立价值，应同时加入 nonlinear size baseline、null graph、chain graph 与 matched-source control。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Would you make nonlinear size baselines and null/chain graph controls mandatory release gates for future GRADE structural claims, rather than post-hoc diagnostics?</em></p><h2 id="_2-paperclip-共享数字员工的真人来源身份进入-operation-time-contract" tabindex="-1">2. Paperclip：共享数字员工的真人来源身份进入 operation-time contract <a class="header-anchor" href="#_2-paperclip-共享数字员工的真人来源身份进入-operation-time-contract" aria-label="Permalink to &quot;2. Paperclip：共享数字员工的真人来源身份进入 operation-time contract&quot;">​</a></h2><p><strong>状态：#13005 MERGED；#13000 DRAFT；#13002 DRAFT</strong></p><p>Paperclip PR <a href="https://github.com/paperclipai/paperclip/pull/13005" target="_blank" rel="noreferrer">#13005</a> 已合入。系统不再根据 task owner 或长驻 provider token 决定 GitHub 身份，而是持久保存<strong>有序 execution identity context</strong>：新的真人指令、steering、queued continuation、retry、delegation、approval、routine 与 Server restart 都保留真正的 originating person。真正执行 <code>git</code> / <code>gh</code> / GitHub gateway 时，才由 operation-time broker 为当前 accepted instruction 的 responsible person 解析凭证；个人 token 不进入长期 provider process。</p><p>真实双账户验收还验证了：A 指令 → B steering → queued A continuation 可以在同一 conversation 中运行，实际 commit/push 身份分别正确；delegated subtask 跨 Server restart 后仍保留原 responsible person。</p><p>同日两条后续方向也很强：</p><ul><li>Draft <a href="https://github.com/paperclipai/paperclip/pull/13000" target="_blank" rel="noreferrer">#13000</a>：private Slack task control，只允许显式映射的真人私聊；消息先持久化再 ACK，mutation 使用 at-most-once fence，结果不确定进入 <code>uncertain</code> 而不自动 replay。</li><li>Draft <a href="https://github.com/paperclipai/paperclip/pull/13002" target="_blank" rel="noreferrer">#13002</a>：durable sandbox work folders，将 task / agent / user / project / repos 分域，周期 checkpoint + final save，让 object storage 而非 sandbox disk 成为耐久层。</li></ul><p><strong>为什么重要：</strong> Employee Identity、Human Principal、Task Owner、Credential Scope、Conversation Continuity 被正式拆开。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 数字员工长期运行时，应将“谁是这个员工”“谁发出当前指令”“当前动作使用谁的 credential/workspace scope”作为不同事实。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：维持最高优先级，并新增 operation-time principal 专项维度。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Will responsible-person identity, Slack attribution and user-scoped work-folder binding converge on one durable authority envelope, so every side effect proves both who instructed it and whose credential/workspace scope it used?</em></p><h2 id="_3-openai-codex-human-verification-进入-secure-enclave-生物识别签名" tabindex="-1">3. OpenAI Codex：Human Verification 进入 Secure Enclave + 生物识别签名 <a class="header-anchor" href="#_3-openai-codex-human-verification-进入-secure-enclave-生物识别签名" aria-label="Permalink to &quot;3. OpenAI Codex：Human Verification 进入 Secure Enclave + 生物识别签名&quot;">​</a></h2><p><strong>状态：MERGED / MERGED</strong></p><p>PR <a href="https://github.com/openai/codex/pull/43624" target="_blank" rel="noreferrer">#43624</a> 已合入 macOS Human Verification：使用 P-256 Secure Enclave key，并通过 Data Protection Keychain 保存；私钥 access-control policy 强制 biometric authentication，每次 challenge signature 创建新的 <code>LAContext</code>。credential 创建/复用/删除/签名还通过 cancellable file lock 做跨进程序列化。</p><p>此前合入的 <a href="https://github.com/openai/codex/pull/43524" target="_blank" rel="noreferrer">#43524</a> 又明确限制：普通用户配置的 MCP Server 即使伪装成官方 Apps MCP 的同名 server，也不能请求真人验证。<code>userVerification</code> capability 只投射给 Host-owned Apps MCP；local identity 还使用 workspace-scoped opaque ChatGPT account user ID，并要求 token workspace 与当前选中 account 一致。</p><p><strong>为什么重要：</strong> Approval 正从“用户点了允许”升级为硬件保护、真人在场、针对 challenge 的密码学证明。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> ADMIN 高风险批准可以分级：普通 UI confirmation、authenticated human approval、device-bound biometric proof；最终 proof 还应绑定 effect digest、principal、workspace/company、authority epoch、nonce/expiry。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Will the signed verification challenge commit to the normalized effect, workspace principal and authority epoch, so biometric proof is specific to one consequential action rather than merely proving user presence?</em></p><h2 id="_4-kazuhiro-sera-seratch-openai-agents-js-两次修复都在回答-谁拥有这份状态" tabindex="-1">4. Kazuhiro Sera（seratch）/ OpenAI Agents JS：两次修复都在回答“谁拥有这份状态？” <a class="header-anchor" href="#_4-kazuhiro-sera-seratch-openai-agents-js-两次修复都在回答-谁拥有这份状态" aria-label="Permalink to &quot;4. Kazuhiro Sera（seratch）/ OpenAI Agents JS：两次修复都在回答“谁拥有这份状态？”&quot;">​</a></h2><p><strong>状态：MERGED / MERGED</strong></p><p>Kazuhiro Sera 本人提交的 PR <a href="https://github.com/openai/openai-agents-js/pull/1841" target="_blank" rel="noreferrer">#1841</a> 与 <a href="https://github.com/openai/openai-agents-js/pull/1842" target="_blank" rel="noreferrer">#1842</a> 均已合入。</p><ul><li>#1841 修复 Multi-Agent handoff 后的 deferred-tool discovery attribution。同名 tool 不能因为历史中曾被 Agent A 搜索，就让 Agent B 误以为自己也已完成 discovery；只有 logical Agent identity 可唯一判定时才恢复归属，歧义则重新搜索。</li><li>#1842 修复 session compaction 并发覆盖：Run 读到历史准备 compaction 期间，如果同一 session 已被其他 writer append，旧 snapshot 不再有资格做整体 replacement。Runner 持有 ephemeral ownership receipt；receipt 过期时放弃自动 replacement。</li></ul><p><strong>为什么重要：</strong> 历史存在不代表我拥有它；同名能力不代表它属于我；曾经读取 snapshot 也不代表现在仍有覆盖权。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Branch/REPORT/并发收敛中，任何“整体替换事实”的操作都应该持有仍有效的 ownership generation；无法证明时只能 append 或重新读取。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Do you see session-compaction ownership and tool-discovery attribution converging on a general Agent/run generation primitive instead of subsystem-specific receipts?</em></p><h2 id="_5-superset-host-升级开始产品化为-backup-→-restart-→-verify-→-rollback" tabindex="-1">5. Superset：Host 升级开始产品化为 backup → restart → verify → rollback <a class="header-anchor" href="#_5-superset-host-升级开始产品化为-backup-→-restart-→-verify-→-rollback" aria-label="Permalink to &quot;5. Superset：Host 升级开始产品化为 backup → restart → verify → rollback&quot;">​</a></h2><p><strong>状态：OPEN</strong></p><p>PR <a href="https://github.com/superset-sh/superset/pull/7270" target="_blank" rel="noreferrer">#7270</a> 让 Host 报告 build/version/install source，并在 Desktop 的 Settings、device picker、workspace compatibility gate 中展示版本状态。对支持的 standalone CLI Host，Owner 可以直接从 Desktop 触发升级；Updater 先锁安装目录、保存 backup，在<strong>同一个 port</strong>重启并验证 successor 的目标版本，失败则自动 rollback。</p><p>团队已做真实 Desktop click 验证：standalone Host 1.26.0 → 1.27.0 约 8 秒。但 production relay/auth、active terminal reconnect、完整 incompatible-workspace gate 仍未真正 E2E；中断升级也可能留下 install lock。</p><p><strong>为什么重要：</strong> 数字员工工作站的升级不能只解决“替换二进制”，而必须有完整 Host lifecycle transaction。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 对 CodeFlowMu Windows 产品版，升级链应至少包括 <strong>Host Version → Compatibility → Upgrade Admission → Backup → Binary Replace → Restart → Successor Verification → Rollback → Session Reconnect</strong>。</p><p><strong>学习：非常高｜竞争风险：高｜雷达判断：保持重点第二圈；若 production relay + active terminal reconnect 真正验证，可升主雷达。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Before replacing a live standalone host, do you plan to drain/fence active agent leases and then prove ownership transition to the verified successor binary?</em></p><h2 id="_6-orca-损坏记录不能-replay-不等于可以删除证据" tabindex="-1">6. Orca：损坏记录不能 replay，不等于可以删除证据 <a class="header-anchor" href="#_6-orca-损坏记录不能-replay-不等于可以删除证据" aria-label="Permalink to &quot;6. Orca：损坏记录不能 replay，不等于可以删除证据&quot;">​</a></h2><p><strong>状态：DRAFT</strong></p><p>Draft PR <a href="https://github.com/stablyai/orca/pull/19399" target="_blank" rel="noreferrer">#19399</a> 修改 journal repair 语义。旧逻辑遇到无法读取的一行，会删除该行和后面整个 suffix；但 provider transcript 无法重构 Orca 自己的 submission receipt，因此这种“修复”可能永久销毁审计证据。</p><p>新方案采用 <strong>sealed recovery generations</strong>：旧 epoch 的原始字节全部保留并 seal，只把已确认可读的 prefix 发布到新 epoch；SQLite trigger 禁止修改/删除 sealed history 与 recovery metadata。未来无法理解数据库/row version 时，也只读，不猜、不迁移、不修。</p><p>最关键的原则是：</p><blockquote><p><strong>Evidence Recoverable ≠ Evidence Safe to Replay。</strong></p></blockquote><p>损坏点之后即使存在看起来合法的 receipt，也只能保留 evidence qualification，不能自动取得 replay authority。</p><p><strong>为什么重要：</strong> 恢复系统必须区分“保留证据”与“允许重放”。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 对损坏 REPORT、Runtime event log、EVAL evidence、authorization receipt，应坚持：旧证据封存不改 → 新 generation 恢复可确定部分 → 不确定 suffix 只保留证据资格，不获得执行资格。</p><p><strong>学习：非常高｜竞争风险：中高｜雷达判断：提高 Orca Recovery / Auditability 权重，但此项仍为 draft。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Do you expect sealed journal generations to become the general evidence-retention primitive for rewind/fork/recovery, so superseded evidence remains immutable without ever regaining replay authority?</em></p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><p>本日最强的共振不是 Session/Resume，而是更底层的一句话：</p><blockquote><p><strong>“状态”正在被拆成：谁拥有、谁授权、能不能覆盖、能不能重放、能不能只作为证据保存。</strong></p></blockquote><p>对 CodeFlowMu/FCoP，可以进一步收敛为：</p><p><strong>Principal Identity → Ownership Generation → Authorization/Verification → Effect Authority → Durable Evidence → Replay Eligibility</strong>。</p><p>其中最后一个 <code>Replay Eligibility</code> 很关键：<strong>能恢复出来的事实，不一定拥有再次执行的权力。</strong></p><h2 id="双源核查说明" tabindex="-1">双源核查说明 <a class="header-anchor" href="#双源核查说明" aria-label="Permalink to &quot;双源核查说明&quot;">​</a></h2><p>本日同时核查公开社交/官方工程博客与 GitHub 一手变更。没有发现 41 位名单中身份可可靠确认、且技术增量高于上述一手变化的本人新社交讨论，因此没有使用营销转发补数。</p>',63)])])}const h=r(n,[["render",i]]);export{g as __pageData,h as default};
